Mainline does the following: apply sampler, and then apply grammar. Then it checks if the sampled token is valid. If the token is invalid, apply grammar first and then the sampler. 

Try this and see if it improves anything:
```
diff --git a/common/sampling.cpp b/common/sampling.cpp
index 0e19de4cb..fa0d6997a 100644
--- a/common/sampling.cpp
+++ b/common/sampling.cpp
@@ -429,7 +429,12 @@ static llama_token llama_sampling_sample_impl(
         GGML_ASSERT(!original_logits.empty());
     }
     llama_token id = 0;
-
+    if (ctx_sampling->grammar != NULL && is_resampling) {
+        // Get a pointer to the logits
+        float* logits = llama_get_logits_ith(ctx_main, idx);
+        // Apply grammar constraints to all candidates
+        llama_grammar_sample(ctx_sampling->grammar, ctx_main, &cur_p);
+    }
     if (temp < 0.0) {
         // greedy sampling, with probs
         llama_sample_softmax(ctx_main, &cur_p);
@@ -484,7 +489,7 @@ static llama_token llama_sampling_sample_impl(

         // If the token is not valid according to the grammar, perform resampling
         if (!is_valid) {
-            LOG("Resampling because token %d: '%s' does not meet grammar rules\n", id, llama_token_to_piece(ctx_main, id).c_str());
+            LOG_INF("Resampling because token %d: '%s' does not meet grammar rules\n", id, llama_token_to_piece(ctx_main, id).c_str());
```

