Hi, me again :P

When two sibling frames overlap spatially within a parent, the [`overlapping` list mechanism](https://github.com/VitalAudio/visage/blob/345d930d0893b6045d52c73b3ed10d8f6b8e1b2f/visage_graphics/layer.cpp#L101) defers rendering of the second child. This deferred child then incorrectly renders on top of later sibling subtrees.

I believe this is actually the root cause of https://github.com/VitalAudio/visage/pull/69 - that was incorrectly marking things as overlapping, which then triggered this bug.

It seems like that `overlapping` list would need to be completely drained before moving on to sibling subtrees.
I've had a quick go at trying to fix this but it seems like it needs a bigger rework of `layer.cpp`.

Here's a repro:

```cpp

#include <visage/app.h>

// BUG: Overlapping sibling frames cause incorrect z-order across subtrees
//
// When a parent frame has two children that overlap spatially, the second
// child gets deferred to an "overlapping" list and rendered later. This
// causes it to incorrectly render on top of sibling subtrees that should
// be in front.
//
// Tree structure:
//   app
//     parent
//       child   (at 50,50)
//       overlay (at 0,0 - overlaps with child)
//     modal (added after parent - should render on top of everything)
//
// Expected: modal covers everything when open
// Actual: overlay renders on top of modal
//
// The bug is in addSubRegions/checkOverlappingRegions in layer.cpp:
// - child gets added to positions
// - overlay overlaps child, so goes to overlapping list
// - modal gets processed
// - overlay finally renders - but now it's on top of modal

int main() {
    visage::ApplicationWindow app;

    visage::Frame parent;
    visage::Frame child;
    visage::Frame overlay;
    visage::Frame modal;

    bool modalOpen = false;

    parent.onDraw() = [&](visage::Canvas& canvas) {
        canvas.setColor(0xffcf6944);  // Orange
        canvas.fill(0, 0, parent.width(), parent.height());
    };

    child.onDraw() = [&](visage::Canvas& canvas) {
        canvas.setColor(0xff8d9f8c);  // Green
        canvas.fill(0, 0, child.width(), child.height());
    };

    overlay.onDraw() = [&](visage::Canvas& c) {
        c.setColor(0xff000000);  // Black border
        c.roundedRectangleBorder(0, 0,
            overlay.width() / c.dpiScale(),
            overlay.height() / c.dpiScale(), 0, 2);
    };

    modal.onDraw() = [&](visage::Canvas& canvas) {
        if (modalOpen) {
            canvas.setColor(0xff44aa44);  // Green
            canvas.fill(0, 0, modal.width(), modal.height());
        }
    };

    // Layout - child and overlay MUST overlap to trigger the bug
    parent.setBounds(20, 20, 260, 260);
    child.setBounds(50, 50, 150, 150);
    overlay.setBounds(0, 0, 260, 260);  // Full size, overlaps child
    modal.setBounds(0, 0, 300, 300);

    parent.addChild(&child);
    parent.addChild(&overlay);

    app.addChild(&parent);
    app.addChild(&modal);

    app.onDraw() = [&](visage::Canvas& canvas) {
        canvas.setColor(0xff222222);
        canvas.fill(0, 0, app.width(), app.height());
    };

    modal.onMouseDown() = [&](const visage::MouseEvent& e) {
        modalOpen = !modalOpen;
        modal.redraw();
    };

    app.setTitle("Click modal area - black border should NOT show through green");
    app.show(300, 300);
    app.runEventLoop();
}

```

