### Issue Category

Behavioral Bug

### Bug Description

When using a tracked value in a style object that's assigned to a variable before being passed to the style attribute, the styles don't update reactively. However, the same reactive value used directly in JSX content continues to work.

I added `backgroundColor: 'red'` just to confirm that the styles are being passed in correctly.
The `@fontSize` rendered as text in the spans is being updated in both components.

I presume that I'm missing something, but I was expecting it to work this way so decided to raise an issue in case it's a bug.

### Reproduction Steps

```
import { track, type Tracked } from 'ripple';

component ComponentReacts({ fontSize }: { fontSize: Tracked<number> }) {
	<span style={{fontSize: `${@fontSize}px`, backgroundColor: 'red'}} class="fontSize">
		{@fontSize}
	</span>
}

component ComponentDoesntReact({ fontSize }: { fontSize: Tracked<number> }) {
	const styles = {
		fontSize: `${@fontSize}px`,
		backgroundColor: 'red',
	};
	<span style={styles} class="fontSize">{@fontSize}</span>
}

export component App() {
	<div>
		let fontSize = track(12);

		{'Font size is reactive:'}
		<ComponentReacts {fontSize} />

		{'Font size isn't reactive'}
		<ComponentDoesntReact {fontSize} />

		<button onClick={() => @fontSize--}>{'-'}</button>
		<button onClick={() => @fontSize++}>{'+'}</button>
	</div>
}

```

### Environment

```markdown
"devDependencies": {
    "eslint": "^9.0.0",
    "@ripple-ts/eslint-plugin": "latest",
    "prettier": "^3.6.2",
    "@ripple-ts/prettier-plugin": "latest",
    "typescript": "^5.9.2",
    "vite": "^7.1.4",
    "@ripple-ts/vite-plugin": "latest",
    "@ripple-ts/typescript-plugin": "latest"
  },
  "dependencies": {
    "ripple": "latest"
  }
```

