Hi there, thank you for the efforts on [#179](https://github.com/hexgrad/kokoro/issues/179)!

First of all I can confirm this is up and running on nextjs wich is great! I have successfully loaded the transformers.js 3.5.1 dev build of onnxruntime-web and kokoro js is finally up and running.

However I'm not sure if my config is wrong or I am using the wrong model, but the execution is taking very long to generate a very simple line.

Ideally I wanted to use the smallest and fastest config as possible, built for running on clients out there in the wild. I have seen some sites using it that made it working really fast on client side and I wonder what could I possibly be doing wrong.


```
'use client';

import { useState, useEffect } from 'react';
import { env, KokoroTTS } from 'kokoro-js';

// Point to local WASM file in /public
env.wasmPaths = {
  wasm: '/onnx/ort-wasm-simd-threaded.jsep.wasm',
};

export default function TTSPage() {
  const [tts, setTTS] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [speaking, setSpeaking] = useState(false);
  const [status, setStatus] = useState<string>('Initializing…');
  const [voiceList, setVoiceList] = useState<string[]>([]);
  const [selectedVoice, setSelectedVoice] = useState<string>('');

  // Load Kokoro model on mount
  useEffect(() => {
    const loadModel = async () => {
      setStatus('Loading model…');
      try {
        const model = await KokoroTTS.from_pretrained(
          'onnx-community/Kokoro-82M-ONNX',
          { dtype: 'q8' }
        );
        setTTS(model);

        const voices = model.voices ? Object.keys(model.voices) : [];
        setVoiceList(voices);
        console.log('[kokoro] ✅ Model loaded');
        console.log('[kokoro] Available voices:', voices);
        console.table(model.voices);
        setStatus(`✅ Model loaded with ${voices.length} voices`);
      } catch (err) {
        console.error('❌ Failed to load model', err);
        setStatus('❌ Failed to load model');
      } finally {
        setLoading(false);
      }
    };

    loadModel();
  }, []);

  // Auto-select first voice
  useEffect(() => {
    if (voiceList.length > 0) {
      setSelectedVoice(voiceList[0]);
    }
  }, [voiceList]);

  const speak = async () => {
    if (!tts || !selectedVoice) return;
    setSpeaking(true);
    const text = "Life is like a box of chocolates. You never know what you're gonna get.";
    setStatus(`🔊 Generating…`);

    try {
      const voiceUsed = selectedVoice || 'af_heart';
      console.log('[kokoro] Generating audio...');
      console.log('🧪 Input Text:', text);
      console.log('🧪 Voice:', voiceUsed);

      // Handle new RawAudio output shape
      const raw = await tts.generate(text, { voice: voiceUsed });
      const result = raw.audio;
      const sampleRate = raw.sampling_rate || 24000;

      console.log('🧪 RawAudio:', raw);
      console.log('🧪 Float32Array?', result instanceof Float32Array);
      console.log('🧪 Length:', result.length);
      console.log('🧪 Sample rate:', sampleRate);

      if (!result || !result.length) {
        console.warn('[kokoro] ❌ Audio buffer is empty or undefined');
        setStatus('❌ Empty audio buffer');
        return;
      }

      const ctx = new AudioContext();
      const buffer = ctx.createBuffer(1, result.length, sampleRate);
      buffer.getChannelData(0).set(result);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start();

      setStatus('✅ Playing audio');
      console.log('[kokoro] ▶️ Playback started');
    } catch (err) {
      console.error('❌ Error during generate/playback', err);
      setStatus('❌ Generate/playback failed');
    } finally {
      setSpeaking(false);
    }
  };

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h2>Kokoro TTS</h2>

      <p>Status: <strong>{status}</strong></p>

      {tts && voiceList.length > 0 && (
        <select
          value={selectedVoice}
          onChange={(e) => setSelectedVoice(e.target.value)}
          disabled={speaking}
        >
          {voiceList.map((id) => (
            <option key={id} value={id}>
              {id}
            </option>
          ))}
        </select>
      )}

      <button onClick={speak} disabled={!tts || speaking || loading}>
        {speaking ? 'Speaking…' : 'Speak'}
      </button>
    </main>
  );
}

```

Thank you!

