There is a new logic for authentication in qwen-cli, this script worked for me: 

~/.claude-code-router/plugins/qwen-cli.js

```
const os = require("os");
const path = require("path");
const fs = require("fs/promises");

// Parámetros configurables.
const OAUTH_DIR = ".qwen";
const OAUTH_CREDS_FILENAME = "oauth_creds.json";
const QWEN_OAUTH_BASE_URL = "https://chat.qwen.ai";
const QWEN_OAUTH_TOKEN_ENDPOINT = `${QWEN_OAUTH_BASE_URL}/api/v1/oauth2/token`;
// Puedes poner el client_id legacy aquí, pero será sobreescrito si existe uno personalizado.
const LEGACY_CLIENT_ID = "f0304373b74a44d2b584a3fb70ca9e56";

// Utilidad para obtener la ruta de credenciales, acepta path custom (tipo ~/xxxx, absoluto, etc)
function getQwenCachedCredentialPath(customPath) {
  if (customPath) {
    if (customPath.startsWith("~/")) {
      return path.join(os.homedir(), customPath.slice(2));
    }
    return path.resolve(customPath);
  }
  return path.join(os.homedir(), OAUTH_DIR, OAUTH_CREDS_FILENAME);
}

class QwenCLITransformer {
  name = "qwen-cli";
  constructor(options = {}) {
    this.options = options;
    // Si quieres path de credenciales personalizado, pásalo en options.qwenCodeOauthPath
    this.credPath = getQwenCachedCredentialPath(this.options.qwenCodeOauthPath);
    this.refreshPromise = null;
  }

  // Carga credenciales desde archivo y permite client_id personalizado o migración automática.
  async getOauthCreds() {
    try {
      const raw = await fs.readFile(this.credPath, "utf-8");
      const creds = JSON.parse(raw);
      // Si existe client_id en el JSON, lo usamos. Si no, legacy client_id.
      this.client_id = creds.client_id || LEGACY_CLIENT_ID;
      this.oauth_creds = creds;
    } catch (error) {
      this.client_id = LEGACY_CLIENT_ID;
      this.oauth_creds = null;
    }
  }

  // Añade buffer de expiración, para evitar race conditions.
  isTokenValid(creds) {
    const TOKEN_REFRESH_BUFFER_MS = 30 * 1000; // 30 segundos extra.
    if (!creds || !creds.expiry_date) return false;
    return Date.now() < creds.expiry_date - TOKEN_REFRESH_BUFFER_MS;
  }

  // Refresh concurrente controlado (no ejecuta dos refresh simultáneos).
  async refreshAccessToken() {
    if (this.refreshPromise) return this.refreshPromise;
    this.refreshPromise = this._doRefreshAccessToken();
    try {
      return await this.refreshPromise;
    } finally {
      this.refreshPromise = null;
    }
  }

  async _doRefreshAccessToken() {
    if (!this.oauth_creds || !this.oauth_creds.refresh_token) {
      throw new Error("No refresh token available in credentials.");
    }
    // Usa client_id personalizado si lo hay.
    const body = new URLSearchParams();
    body.append("grant_type", "refresh_token");
    body.append("refresh_token", this.oauth_creds.refresh_token);
    body.append("client_id", this.client_id);

    const response = await fetch(QWEN_OAUTH_TOKEN_ENDPOINT, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body,
    });

    if (!response.ok) {
      const errorText = await response.text();
      // Registramos el error en el JSON para debugging.
      let current_creds = this.oauth_creds || {};
      if (!current_creds.refresh_error) {
        current_creds.refresh_error = {
          error: response.status,
          error_description: errorText,
          ts: Date.now()
        };
        await fs.writeFile(this.credPath, JSON.stringify(current_creds, null, 2));
      }
      throw new Error(`Token refresh failed: ${response.status} ${response.statusText} - ${errorText}`);
    }
    const tokenData = await response.json();
    if (tokenData.error) {
      throw new Error(`Token refresh failed: ${tokenData.error} - ${tokenData.error_description}`);
    }
    // Actualiza expiry con buffer, conserva client_id, refresh_token, resource_url si lo hay.
    const new_creds = {
      ...this.oauth_creds,
      access_token: tokenData.access_token,
      refresh_token: tokenData.refresh_token || this.oauth_creds.refresh_token,
      expiry_date: Date.now() + tokenData.expires_in * 1000 - 60 * 1000,
      client_id: (tokenData.client_id || this.client_id),
    };
    if (tokenData.resource_url) new_creds.resource_url = tokenData.resource_url;
    await fs.writeFile(this.credPath, JSON.stringify(new_creds, null, 2));
    this.oauth_creds = new_creds;
    return new_creds;
  }

  // Proceso seguro de autenticación: carga credenciales y refresh si es necesario.
  async ensureAuthenticated() {
    if (!this.oauth_creds) await this.getOauthCreds();
    if (!this.isTokenValid(this.oauth_creds)) await this.refreshAccessToken();
  }

  // Inyección del token de acceso y User-Agent en la petición.
  async transformRequestIn(request, provider) {
    await this.ensureAuthenticated();

    if (request.stream) {
      request.stream_options = { include_usage: true };
    }
    return {
      body: request,
      config: {
        headers: {
          Authorization: `Bearer ${this.oauth_creds.access_token}`,
          "User-Agent": "QwenCode/v22.12.0 (darwin; arm64)",
        },
      },
    };
  }
}

module.exports = QwenCLITransformer;
```

